# Backfills data for orders created before CoreCart 1.0, then makes the order
# number unique and mandatory. Non-destructive: existing values are only added to.

from django.db import migrations, models


def backfill(apps, schema_editor):
    Order = apps.get_model("orders", "Order")
    OrderItem = apps.get_model("orders", "OrderItem")

    # The old admin action wrote an invalid "completed" status.
    Order.objects.filter(status="completed").update(status="delivered")

    for order in Order.objects.filter(order_number__isnull=True).order_by("pk"):
        order.order_number = f"CC{order.created_at:%y%m%d}{order.pk:06d}"[:20]
